-- Real, destination-specific FAQ content for every tour (shown on both
-- /expeditions/{slug} and /lp/{slug} via TourFAQSection, since both read the
-- same expeditions.faqs jsonb column). Deliberately distinct from the generic
-- company-wide FAQ on the homepage (FAQSection.tsx) -- these answer what's
-- actually unique to each destination: visas, permits, safety, restrictions.

UPDATE public.expeditions SET faqs = '[{"question": "Do I need a visa for Mongolia?", "answer": "Most Western passport holders (US, UK, EU, Canada, Australia) can enter Mongolia visa-free for up to 30 days. Check your specific nationality before booking, but for the vast majority of applicants no advance visa is required."}, {"question": "How physically demanding is this expedition?", "answer": "You''ll spend several hours a day on horseback across open steppe and rocky terrain, often in freezing temperatures. You don''t need riding experience, but you should be comfortable in the saddle for long stretches and able to handle cold, basic camp conditions."}, {"question": "Will I actually get to hunt with the eagle?", "answer": "You''ll be present for a real hunting demonstration with the family''s golden eagle and can hold the bird under supervision, but this is their working animal and livelihood, not a tourist prop. How much hands-on time you get depends on the family and the day."}, {"question": "What''s the weather like on this trip?", "answer": "The Altai in western Mongolia is harsh and dry, with temperatures that can drop well below freezing even outside winter, especially at night and at altitude. Layered cold-weather gear is essential regardless of when you travel."}]'::jsonb WHERE slug = 'altai-mongolia-eagle-hunters';
UPDATE public.expeditions SET faqs = '[{"question": "Is it safe to visit Kashmir right now?", "answer": "We only run this expedition when our on-the-ground contacts confirm the situation is stable, and we route around active friction points. That said, this is a militarized border region and conditions can shift quickly, we brief every applicant honestly on the current situation before departure."}, {"question": "Do I need special permits to get close to the Line of Control?", "answer": "Yes. Certain areas near the LoC require an Inner Line Permit or military clearance that we arrange in advance through local contacts. Some sections are simply off-limits regardless of permit, and we won''t take you somewhere access isn''t legitimately secured."}, {"question": "Can I photograph military positions or checkpoints?", "answer": "No. Photographing military installations, checkpoints, or personnel is illegal in this region and taken seriously by the Indian Army. Your guide will tell you clearly where cameras need to stay away, and we expect that to be respected without exception."}, {"question": "Will this trip be affected by India-Pakistan tensions?", "answer": "It can be. We monitor the situation continuously and will postpone or reroute if tensions escalate before your departure. If we cancel for security reasons, you''re fully refunded per our standard policy."}]'::jsonb WHERE slug = 'indian-kashmir-line-of-control';
UPDATE public.expeditions SET faqs = '[{"question": "Is Transnistria actually safe to visit?", "answer": "Yes. Despite the Soviet iconography and the breakaway-state status, Transnistria is calm and orderly for visitors, arguably more so than many recognized destinations. The main friction is bureaucratic, not physical danger."}, {"question": "Do I need a Moldovan visa, and does a Transnistria stamp cause problems?", "answer": "You enter through Moldova, so standard Moldovan entry rules apply for your nationality. Transnistria itself issues a separate migration slip at its border, not a passport stamp, so it won''t complicate your Moldovan entry or exit."}, {"question": "Will crossing into Transnistria cause issues re-entering Moldova?", "answer": "No. Moldova doesn''t restrict re-entry based on a Transnistria visit, it''s still legally Moldovan territory in Chisinau''s eyes. Keep your Transnistrian migration slip until you cross back, you may be asked for it."}, {"question": "Will my phone and cards work there?", "answer": "Mobile data roams in from Moldova reasonably well in Tiraberg (Tiraspol) and along main roads. Cards are unreliable outside a few hotels, this is a cash economy (Transnistrian rubles, exchanged on entry), so budget for that."}]'::jsonb WHERE slug = 'transnistria-soviet-ghost-state';
UPDATE public.expeditions SET faqs = '[{"question": "Is Abkhazia safe and can I actually visit it?", "answer": "Yes, it''s calm and used to receiving visitors, mostly from Russia. Access for Western travelers is more about logistics and permissions than physical risk, we handle both."}, {"question": "Will visiting Abkhazia cause problems if I''ve also visited Georgia?", "answer": "Potentially, yes, this is the single biggest thing to know before booking. Georgia considers entry into Abkhazia from Russia (the only practical route) illegal entry into Georgian territory, and has in rare cases denied entry or caused issues for travelers with Abkhazian stamps or records. If a future Georgia trip matters to you, tell us before you apply."}, {"question": "Do I need a special permit to enter?", "answer": "Yes, a formal entry permit issued by Abkhazia''s Ministry of Foreign Affairs, which we arrange for you in advance. You cannot get one at the border on arrival."}, {"question": "What currency and language should I expect?", "answer": "The Russian ruble is the working currency, though Abkhazia also has its own commemorative currency that isn''t used day to day. Russian is the practical lingua franca alongside Abkhaz, English is rare outside your guide."}]'::jsonb WHERE slug = 'abkhazia-suspended-republic';
UPDATE public.expeditions SET faqs = '[{"question": "Is it safe to travel to Afghanistan under Taliban rule?", "answer": "The Wakhan Corridor is ethnically Wakhi and Kyrgyz, geographically isolated, and has a fundamentally different security profile from the rest of Afghanistan, it''s one of the few parts of the country where organized trekking has continued. We still brief every applicant in detail on the current Taliban administration''s rules and the real, non-zero risks of traveling in Afghanistan at all."}, {"question": "How do I get a visa, and are there restrictions on what I can do?", "answer": "We handle the visa application through our local partners once you''re accepted. Expect rules around photography of people (always ask first), alcohol (strictly prohibited), and limited independent movement, you''ll be with your guide and local fixers throughout."}, {"question": "What are the rules for women on this trip?", "answer": "Female travelers should pack conservative, modest clothing (long sleeves, loose fit, a headscarf) and expect more restricted interaction with local men than male travelers. We''ll walk you through specifics during your pre-departure briefing so there are no surprises."}, {"question": "How fit do I need to be for this trek?", "answer": "Very. You''re on foot or horseback at altitude (much of the route sits above 3,500m) for multiple days, with cold nights and no infrastructure to fall back on. Prior high-altitude trekking experience is strongly recommended, not just gym fitness."}]'::jsonb WHERE slug = 'afghanistan-wakhan-corridor';
UPDATE public.expeditions SET faqs = '[{"question": "Is Bosnia safe to visit today?", "answer": "Yes, entirely. Sarajevo and the surrounding region are peaceful and well set up for tourism, three decades on from the war. The history is visible (bullet-scarred buildings, memorials) but the present-day risk is essentially nonexistent."}, {"question": "Do I need a visa for Bosnia and Herzegovina?", "answer": "Most Western passport holders can enter visa-free for up to 90 days. Check your specific nationality, but this is one of the more straightforward entries on our roster."}, {"question": "How is the war history handled, is it heavy going?", "answer": "Directly and honestly, through guides who often lived through the siege themselves, but the tone is memory and understanding, not spectacle. Expect real, sometimes difficult conversations, not just monuments."}, {"question": "What''s the fitness level required?", "answer": "Low to moderate. This is mostly walking through the city and a hike up the hills above Sarajevo for the views, nothing technical or extreme. Reasonable everyday fitness is enough."}]'::jsonb WHERE slug = 'bosnia-ghost-frontlines';
UPDATE public.expeditions SET faqs = '[{"question": "Is it safe to visit Chechnya under the current government?", "answer": "For visitors specifically, yes, Grozny is tightly controlled and among the safer cities in the region precisely because of how closely it''s policed. That control also shapes what you should and shouldn''t say or photograph, which we brief in detail beforehand."}, {"question": "Will I be monitored or need special permission?", "answer": "You don''t need a separate permit beyond your Russian visa, but assume a level of official awareness of foreign visitors that''s higher than elsewhere in Russia. Your guide manages this relationship, it''s routine for them."}, {"question": "What are the rules around photography and dress?", "answer": "Ask before photographing people, government buildings, or security personnel, and dress modestly, especially around the mosque (headscarves required for women). Chechnya is a conservative Muslim republic and this is expected of all visitors, not just women."}, {"question": "Can women travel comfortably on this trip?", "answer": "Yes, with the same modest dress expectations as anywhere else in the Muslim Caucasus. You''ll be respected as a guest, local customs around gender interaction are just more conservative than in Western Europe."}]'::jsonb WHERE slug = 'chechnya-authority-reconstruction';
UPDATE public.expeditions SET faqs = '[{"question": "Is the Darién Gap safe given the news about migrant crossings?", "answer": "We operate in a different part of the Darién than the migrant trail, with vetted local guides who know exactly which areas are stable and which to avoid entirely, including any routes used by criminal groups. We will not take you through active trafficking corridors, full stop."}, {"question": "What vaccinations or health prep do I need?", "answer": "Yellow fever vaccination is required, and we strongly recommend being current on typhoid, hepatitis A/B, and tetanus. Malaria prophylaxis is also worth discussing with a travel clinic given the jungle environment."}, {"question": "How physically demanding is jungle trekking?", "answer": "Genuinely demanding: multi-hour days in heat and humidity, river crossings, uneven terrain, and no way to shortcut out once you''re in. You should be in solid physical condition and have some prior trekking experience."}, {"question": "Will we encounter migrants crossing the jungle?", "answer": "It''s possible but not the focus of this route, and your guides are trained on how to handle any such encounter safely and respectfully if it happens. This isn''t a trip built around the migration crisis, it''s built around the jungle and the Emberá communities who live there."}]'::jsonb WHERE slug = 'darien-jungle-friction';
UPDATE public.expeditions SET faqs = '[{"question": "Is Eritrea safe to visit?", "answer": "Yes, for tourists it''s one of the calmer and more orderly countries on our roster, crime against visitors is rare. Its reputation comes from press freedom and government control issues, not physical danger to travelers."}, {"question": "How hard is it to get an Eritrea visa?", "answer": "Notoriously slow but doable: tourist visas are processed through Eritrean embassies and typically require a locally arranged invitation, which we handle as part of your booking. Build in extra lead time, this isn''t a same-week visa."}, {"question": "Are foreigners free to move around and take photos?", "answer": "Movement and photography are more restricted than in most countries, certain areas require permits and military/government sites are strictly off-limits to cameras. You''ll travel with a licensed local guide throughout, which is both the law and the practical way to navigate it."}, {"question": "What''s the internet and phone situation?", "answer": "Very limited. Eritrea has some of the lowest internet penetration in the world and connectivity is slow and heavily monitored where it exists at all. Tell people at home to expect silence for the duration of the trip."}]'::jsonb WHERE slug = 'eritrea-sealed-state';
UPDATE public.expeditions SET faqs = '[{"question": "Is it safe for Westerners to visit Iran?", "answer": "Physical safety for tourists inside Iran is generally good, Iranians are famously welcoming to foreign visitors. The real complications are diplomatic and administrative, not personal danger, and we walk every applicant through them honestly."}, {"question": "What''s different for US, UK, and Canadian citizens?", "answer": "Nationals of these three countries must book through a licensed Iranian tour operator with a state-approved guide accompanying them at all times, no independent travel is permitted. We arrange this as standard for anyone from these countries."}, {"question": "Will my cards work in Iran?", "answer": "No. International sanctions mean Visa, Mastercard, and virtually all foreign cards are unusable in Iran. This is a cash trip, bring euros or dollars to exchange on arrival, we''ll tell you how much to budget."}, {"question": "What''s the dress code, especially for women?", "answer": "Women must wear a headscarf and loose-fitting clothing covering arms and legs in all public spaces, by law, not just custom. Men should also avoid shorts and sleeveless shirts outside of private spaces. We cover specifics in your pre-departure briefing."}]'::jsonb WHERE slug = 'iran-lut-desert';
UPDATE public.expeditions SET faqs = '[{"question": "Is Iraqi Kurdistan safe, and is it different from the rest of Iraq?", "answer": "Yes, meaningfully different. The Kurdistan Region has its own security forces, has been stable for years, and is a genuinely different risk profile from central and southern Iraq, which is why it''s one of the more accessible frontier destinations on our list."}, {"question": "Do I need a separate visa for Kurdistan?", "answer": "Most Western nationalities receive a free visa on arrival at Erbil International Airport, valid specifically for the Kurdistan Region, this is separate from and doesn''t require a broader Iraqi visa."}, {"question": "What''s the security situation near the mountains and the Iran/Turkey border?", "answer": "We stay within areas the Kurdistan Regional Government and our local security contacts confirm as stable, and avoid contested zones near Iraq-administered Kirkuk or active PKK-Turkey friction points. Routes are reassessed before every departure."}, {"question": "How fit do I need to be for the trekking sections?", "answer": "Moderate fitness is enough, the mountain trek is 4 to 6 hours on established trails, not technical climbing. Comfortable, broken-in hiking boots matter more than elite fitness here."}]'::jsonb WHERE slug = 'iraqi-kurdistan-peshmerga-lines';
UPDATE public.expeditions SET faqs = '[{"question": "Is Kaliningrad safe to visit given the war in Ukraine?", "answer": "For visitors who can legally get there, yes, Kaliningrad itself is far from the front and daily life is normal. The real barrier is getting in, not safety once you''re there."}, {"question": "How do I even get a Russian visa right now?", "answer": "It''s harder than before the war: most direct flights from Europe are suspended, so entry usually means a Russian e-visa (available to many nationalities) and travel via a connecting country. We advise on the current routing when you apply, it changes."}, {"question": "Will Western sanctions affect me while I''m there?", "answer": "Yes, directly. Foreign Visa and Mastercard cards do not work in Russia, including Kaliningrad, this is a cash trip. Bring euros or dollars to exchange on arrival."}, {"question": "Are there restrictions based on my nationality?", "answer": "Some countries'' citizens face additional scrutiny or are barred from certain visa categories entirely, this shifts with the political situation. Tell us your nationality when you apply and we''ll confirm feasibility before you commit to anything."}]'::jsonb WHERE slug = 'kaliningrad-soviet-exclave';
UPDATE public.expeditions SET faqs = '[{"question": "Is Lebanon safe to visit given regional tensions?", "answer": "We only run this expedition when the security situation, particularly along the Israel border and in the south, is stable, and Beirut, the Bekaa Valley, and the historic coastal cities are unaffected by that friction. We reassess before every departure and will reroute or postpone if needed."}, {"question": "Do I need a visa for Lebanon?", "answer": "Most Western nationalities receive a visa on arrival, free or low-cost, at Beirut airport. It''s one of the more straightforward entries on our roster."}, {"question": "Will we go anywhere near the southern border or Hezbollah-controlled areas?", "answer": "No. This itinerary stays in Beirut, the Bekaa Valley, and the historic coast (Tyre, Sidon), well clear of the volatile southern border region. We don''t route trips through active friction zones."}, {"question": "What does Lebanon''s economic crisis mean for tourists?", "answer": "Mainly that this is a cash economy, US dollars are widely accepted and often preferred over the Lebanese lira, whose value has collapsed. ATMs are unreliable, bring the cash you need."}]'::jsonb WHERE slug = 'lebanon-business-of-war';
UPDATE public.expeditions SET faqs = '[{"question": "Is Libya safe to visit given its civil war history?", "answer": "Tripoli and the western coastal region we visit have been stable for an extended period under the current administration, which is what makes this trip possible at all. It''s still Libya, we brief you honestly on the current political situation and what''s genuinely off-limits."}, {"question": "How hard is it to get a Libyan visa?", "answer": "Difficult and slow through normal channels, tourist visas require a locally arranged invitation and sponsorship, which we handle directly given our on-the-ground relationships. This is not a trip you can arrange independently."}, {"question": "Will we have armed security or escorts?", "answer": "In parts of the itinerary, yes, arranged through vetted local contacts as a standard precaution, not because of an active, specific threat. This is disclosed upfront, not sprung on you."}, {"question": "What''s the current political situation in Libya?", "answer": "Libya remains divided between rival administrations in the west and east, we operate exclusively in the western, Tripoli-based area under the internationally recognized government''s territory, and don''t cross into contested or eastern zones."}]'::jsonb WHERE slug = 'libya-gaddafi-legacy';
UPDATE public.expeditions SET faqs = '[{"question": "Is Mauritania safe given Sahel terrorism concerns?", "answer": "Mauritania has been notably more stable than its Sahel neighbors (Mali, Niger, Burkina Faso) for over a decade, largely due to a deliberate government counterterrorism strategy. We stay within the well-traveled Adrar region corridor, not the more volatile eastern border areas."}, {"question": "Do I need a visa for Mauritania?", "answer": "Yes, most nationalities need a visa, obtainable in advance or on arrival depending on your passport, we confirm the current process when you apply."}, {"question": "How physically demanding is the desert travel?", "answer": "Moderate: long days in 4x4s and some camel riding and walking on dunes, in serious heat. You don''t need technical skills, but heat tolerance and a genuine ability to stay hydrated and disciplined matter."}, {"question": "How do you manage heat and water safety in the Sahara?", "answer": "Vehicles carry substantial water reserves beyond what you''ll drink, and your guides are experienced in desert travel and heat illness recognition. That said, this is real desert, not a resort, and you''re expected to take hydration seriously yourself."}]'::jsonb WHERE slug = 'mauritania-lost-cities-sahara';
UPDATE public.expeditions SET faqs = '[{"question": "Is it safe to visit North Korea as a tourist?", "answer": "Physical safety for tourists who follow the rules is generally good, incidents are rare and almost always tied to someone breaking a clearly stated rule. The real risk is legal, not physical, which is why we''re strict about briefing every rule before you go."}, {"question": "Will I be watched or restricted the entire time?", "answer": "Yes, constantly, you''re with state-assigned guides at all times and cannot move independently, this is simply how North Korea operates for all foreign visitors, not something specific to us. Expect a curated, closely managed experience."}, {"question": "Can I bring my phone, and will I have internet?", "answer": "You can bring a phone, but there is no public internet access for tourists, only limited, guide-approved connectivity in specific circumstances. Assume you''re offline for the entire trip and tell people at home in advance."}, {"question": "What am I allowed to photograph?", "answer": "Landscapes, monuments, and approved sites are generally fine, but never photograph soldiers, military installations, or anything your guide tells you not to, and never take unflattering angles of leader statues or portraits. Your guide will tell you clearly in the moment, listen to them."}]'::jsonb WHERE slug = 'north-korea-total-system-immersion';
UPDATE public.expeditions SET faqs = '[{"question": "Do I need a special permit for the Pamirs?", "answer": "Yes, a GBAO (Gorno-Badakhshan) permit is required in addition to your Tajik visa to travel through this region, we arrange both as part of your booking."}, {"question": "How demanding is this trip at altitude?", "answer": "Significant: you''ll spend days above 3,500m and cross a pass over 4,600m, with real risk of altitude effects if you''re not acclimatizing properly. Prior high-altitude experience is a genuine asset, this isn''t a trip to attempt as your first time at elevation."}, {"question": "Is Tajikistan safe, especially near the Afghan border?", "answer": "The Pamir Highway route has been a stable, well-established travel corridor for years despite running close to Afghanistan for stretches, we monitor the border situation continuously and adjust if needed. Tajik border guard presence along the route is actually part of what keeps it secure."}, {"question": "What are the roads and vehicles like?", "answer": "Rough. Much of the Pamir Highway is unpaved, potholed, or partially washed out, and you''ll be in sturdy 4x4s built for exactly this. Expect long, bumpy driving days, not a smooth ride."}]'::jsonb WHERE slug = 'pamir-highway-tajikistan';
UPDATE public.expeditions SET faqs = '[{"question": "What vaccinations do I need for Papua New Guinea?", "answer": "Malaria prophylaxis is essential given the region, alongside routine vaccinations and typhoid/hepatitis A. Talk to a travel clinic 6 to 8 weeks out, some recommendations depend on exactly where you''re coming from."}, {"question": "Is PNG safe given its reputation for crime and tribal conflict?", "answer": "Crime is a real issue in PNG''s cities, particularly Port Moresby, which is why we minimize time there and move quickly into the Sepik and highlands, where our local guides and relationships with village communities keep the trip on solid ground. Tribal tension exists but isn''t something tourists on an escorted trip like this typically encounter."}, {"question": "How physically demanding is this multi-region trip?", "answer": "Variable but real: canoe travel and village walking in the Sepik, altitude and trekking in the Baliem Valley, and long transfer days between three separate regions. It''s more about stamina and flexibility than technical skill."}, {"question": "Do I need a special permit for West Papua?", "answer": "Yes, West Papua is Indonesian-administered and access for foreigners is periodically restricted or requires a surat jalan (travel permit), which we monitor and arrange when the route is open. If access is closed at the time of your trip, we''ll tell you before you book, not after."}]'::jsonb WHERE slug = 'papua-sepik-baliem-bougainville';
UPDATE public.expeditions SET faqs = '[{"question": "Is it safe to visit Socotra given Yemen''s civil war?", "answer": "Socotra has stayed largely outside the mainland conflict due to its geographic isolation and different administration, which is exactly why it remains visitable while the Yemeni mainland doesn''t. We monitor the island''s specific situation, not just Yemen''s headline news, before every departure."}, {"question": "How do I even get to Socotra?", "answer": "By charter flight, typically routed via UAE rather than through mainland Yemen, this is arranged as part of your booking, not something you book yourself. Commercial options are limited and change, so timing is coordinated closely around available charters."}, {"question": "What are the camping and facilities like?", "answer": "Basic. Much of this trip is wild camping with no infrastructure, no signal, and minimal facilities, that''s the isolation you''re signing up for. A few nights are in simple guesthouses near Hadibo."}, {"question": "How fit do I need to be?", "answer": "Good general fitness for multi-day trekking across dunes, canyons, and mountain terrain in heat, with a pack. Not technical, but sustained."}]'::jsonb WHERE slug = 'socotra-extreme-isolation';
UPDATE public.expeditions SET faqs = '[{"question": "Is Somaliland safe, and how is it different from Somalia?", "answer": "Somaliland has functioned as a stable, self-governing territory with its own government, currency, and security forces for over three decades, a genuinely different situation from the instability associated with southern Somalia. It''s one of the safer entries on our roster precisely because of that separation."}, {"question": "Do I need a visa, and is Somaliland internationally recognized?", "answer": "No country recognizes Somaliland as independent, but it issues its own visas, which we arrange for you, that Somalia does not control or interfere with in practice."}, {"question": "What about al-Shabaab, is that a risk here?", "answer": "Al-Shabaab''s activity is concentrated in southern and central Somalia, not Somaliland, which is a meaningful part of why this region remains accessible. Local security presence is visible and taken seriously."}, {"question": "What''s the dress code and cultural expectations?", "answer": "Conservative dress is expected, especially for women (headscarf, loose clothing covering arms and legs), Somaliland is a devout Muslim society. Alcohol is effectively unavailable, plan accordingly."}]'::jsonb WHERE slug = 'somaliland-unrecognized-territory';
UPDATE public.expeditions SET faqs = '[{"question": "Is South Ossetia safe, and who actually controls it?", "answer": "It''s calm and stable day to day, administered as a de facto independent territory with Russian military support since the 2008 war, most Western governments consider it Georgian territory under occupation. For visitors, the practical experience is orderly, the politics are what''s complicated."}, {"question": "Can I enter via Georgia, or only through Russia?", "answer": "Only through Russia, via North Ossetia and the Roki Tunnel, Georgia does not control or permit access to South Ossetia from its side and entering that way isn''t possible. This means you''ll need a Russian visa for this trip."}, {"question": "Will this cause problems for a future trip to Georgia?", "answer": "Potentially, yes, similar to Abkhazia, Georgia treats entry into South Ossetia via Russia as illegal entry into Georgian territory and has occasionally flagged travelers over it. If Georgia is somewhere you plan to visit later, raise this with us before applying."}, {"question": "What language and currency should I expect?", "answer": "Russian is the practical working language alongside Ossetian, and the Russian ruble is the currency used. English is very limited outside your guide."}]'::jsonb WHERE slug = 'south-ossetia-unrecognized-frontier';
UPDATE public.expeditions SET faqs = '[{"question": "How cold does it actually get, and what gear is provided?", "answer": "Temperatures regularly sit well below freezing, and wind chill on the glacier makes it feel far colder. We provide technical outer layers and safety equipment, you''re responsible for solid thermal base layers, we send a detailed packing list once you''re confirmed."}, {"question": "Are polar bears a real risk?", "answer": "Yes, genuinely, Svalbard has more polar bears than people, which is why armed guides accompany every trip outside Longyearbyen by law, not as a dramatic touch. You will not be off checking terrain unescorted at any point."}, {"question": "How physically demanding is the snowmobiling and glacier trekking?", "answer": "Moderate: snowmobiling requires no special skill but is physically tiring over long distances in the cold, and glacier walking involves careful, guided movement around crevasses. Cold tolerance matters as much as raw fitness here."}, {"question": "When''s the best time to go, midnight sun or polar night?", "answer": "Both are offered on different dates and are genuinely different experiences, midnight sun (summer) means 24-hour daylight, polar night (winter) means the aurora and total darkness at midday. Pick based on which extreme interests you more, not one over the other objectively."}]'::jsonb WHERE slug = 'svalbard-arctic-survival';
UPDATE public.expeditions SET faqs = '[{"question": "Is Syria safe to visit after Assad''s fall?", "answer": "The regions on this itinerary, Damascus, Homs, the coast, and Aleppo, have stabilized enough for us to run this trip, but Syria remains in a genuine transitional period and we monitor the situation closely up to departure. We are direct with every applicant about the real, ongoing uncertainty here, this is frontier travel in the truest sense right now."}, {"question": "Do I need a visa, and has that changed since the transition?", "answer": "Visa processes are still evolving under the new administration and can change with little notice, we confirm the current requirement for your nationality at the time of application rather than publishing a fixed answer that could go stale."}, {"question": "Are all the regions on this route equally stable?", "answer": "No, conditions vary city to city and can shift week to week, which is why our itinerary and route are confirmed close to departure based on the latest on-the-ground assessment, not fixed months in advance."}, {"question": "Will we see active reconstruction, and is tourist infrastructure ready?", "answer": "Yes to both, expect visible rebuilding efforts and conversations with residents doing that work firsthand, alongside genuinely basic infrastructure in places. This is an early-access trip to a country still finding its footing, not a polished tourist circuit."}]'::jsonb WHERE slug = 'syria-after-the-regime';
UPDATE public.expeditions SET faqs = '[{"question": "How hard is it to get a Turkmenistan visa?", "answer": "Very, it''s consistently ranked among the world''s most difficult visas to obtain, requiring a letter of invitation and lengthy processing. We handle the full application through our local partners, but build significant lead time into your application."}, {"question": "Will I be free to move around, or is everything guided?", "answer": "Everything is guided, independent movement isn''t realistically possible or legally straightforward for foreign tourists in Turkmenistan. You''ll be with a licensed local guide for the entire trip, this is standard for all visitors, not specific to us."}, {"question": "Is internet or phone access available?", "answer": "Extremely limited. Turkmenistan has some of the most restricted internet access in the world, most Western sites and apps are blocked and connectivity is slow where it exists. Assume minimal to no contact home for the trip''s duration."}, {"question": "Am I being watched or monitored as a tourist?", "answer": "Assume a higher level of state awareness of foreign visitors than almost anywhere else you''ll travel, this is simply the nature of Turkmenistan''s system. It doesn''t typically translate into problems for tourists who follow their guide''s direction."}]'::jsonb WHERE slug = 'turkmenistan-closed-kingdom';
UPDATE public.expeditions SET faqs = '[{"question": "Is DR Congo safe given the conflict in the east?", "answer": "The M23 and related conflict is concentrated in specific areas of North Kivu, we run this trip only when Virunga National Park''s own security assessment and our on-the-ground contacts confirm the gorilla sector and Goma access are stable, and we cancel or reroute immediately if that changes. This is genuinely one of the higher-risk trips we run, and we''re upfront about that with every applicant."}, {"question": "What vaccinations and health prep are required?", "answer": "Yellow fever vaccination is mandatory for entry, and malaria prophylaxis, typhoid, and hepatitis A/B are strongly recommended. A pre-trip consultation with a travel clinic is essential given the region."}, {"question": "How physically demanding is gorilla trekking and the volcano climb?", "answer": "Genuinely demanding: the Nyiragongo climb is a steep multi-hour ascent to nearly 3,500m, and gorilla trekking involves unpredictable jungle terrain that can mean anywhere from 1 to several hours of hiking each way. Solid cardiovascular fitness is required for both."}, {"question": "Are the park rangers armed, and why?", "answer": "Yes. Virunga''s rangers are armed and trained for both wildlife protection and security in a genuinely volatile region, more rangers have died defending this park than almost any other in the world. Their presence is a core part of what makes the gorilla trek possible safely."}]'::jsonb WHERE slug = 'virunga-militarized-gorilla-trek';
UPDATE public.expeditions SET faqs = '[{"question": "Is it ethical or safe to visit Xinjiang given the human rights situation?", "answer": "This is a fair question and one we think you should sit with. We go to see and understand the reality directly, including its surveillance apparatus, rather than only reading about it, and we''re honest that your presence and spending have real, debated implications, we lay out that context clearly before you commit."}, {"question": "Will I be under surveillance the entire trip?", "answer": "Yes, assume constant monitoring, facial recognition checkpoints are routine throughout the region, this is simply Xinjiang''s baseline reality for everyone, residents and visitors alike, not something specific to your trip."}, {"question": "Do I need a special permit beyond a Chinese visa?", "answer": "A standard Chinese visa is sufficient for the areas on this itinerary, no separate permit is required, though document checks at checkpoints are frequent and you should carry your passport at all times."}, {"question": "What''s the internet situation, will a VPN work?", "answer": "China''s Great Firewall blocks most Western apps and sites, and VPN access is unreliable and increasingly restricted, especially in Xinjiang specifically. Don''t count on a VPN working, plan for limited connectivity."}]'::jsonb WHERE slug = 'xinjiang-surveillance-frontier';
